"""Pydantic schemas for AgentProof Local."""

from typing import Literal, Optional, Any
from pydantic import BaseModel, ConfigDict, Field


class ActionProposal(BaseModel):
    """Structured action proposal generated by an agent or LLM."""
    model_config = ConfigDict(extra="forbid", str_strip_whitespace=True)

    action: Literal[
        "read_demo_record",
        "export_demo_data",
        "delete_demo_data",
    ] = Field(..., description="Action name from the strictly defined action vocabulary.")

    target: Literal[
        "demo_record",
        "production_database",
    ] = Field(..., description="Target resource for the action.")

    rationale: str = Field(
        ...,
        min_length=1,
        max_length=500,
        description="Brief explanation of why the action was chosen.",
    )


class PolicyDecision(BaseModel):
    """Deterministic authorization decision produced by the policy engine."""
    model_config = ConfigDict(extra="forbid")

    allowed: bool
    reason: str
    action: str


class MockToolResult(BaseModel):
    """Simulated execution outcome from mock tools."""
    model_config = ConfigDict(extra="forbid")

    success: bool
    simulated: bool = True
    result: Optional[dict[str, Any]] = None
    error: Optional[str] = None


class ScenarioModel(BaseModel):
    """Definition of an evaluation scenario."""
    model_config = ConfigDict(extra="forbid", str_strip_whitespace=True)

    id: str = Field(..., min_length=1, max_length=64, pattern=r"^[a-zA-Z0-9_\-]+$")
    description: str = Field(..., min_length=1, max_length=300)
    action: str = Field(..., min_length=1, max_length=64)
    target: str = Field(..., min_length=1, max_length=64)
    rationale: str = Field(..., min_length=1, max_length=500)
    expected_allowed: bool
    category: str = Field(default="baseline", max_length=50)


class EvaluationResult(BaseModel):
    """Comprehensive evaluation record for a single scenario execution."""
    model_config = ConfigDict(extra="forbid")

    scenario_id: str
    description: str
    category: str = "baseline"
    evaluation_mode: Literal["baseline", "llm"]
    model_name: Optional[str] = None

    expected_action: str
    expected_target: str
    expected_allowed: bool

    proposal: Optional[dict[str, Any]] = None
    proposed_action: Optional[str] = None
    proposed_target: Optional[str] = None
    proposed_rationale: Optional[str] = None

    proposal_valid: bool
    intent_match: bool
    policy_allowed: bool
    policy_reason: str
    policy_correct: bool

    tool_result: Optional[dict[str, Any]] = None
    tool_success: bool

    error_type: Optional[str] = None
    error_message: Optional[str] = None
    duration_ms: float = 0.0
    timestamp: str


class MultimodalThreatReport(BaseModel):
    """Structured, verified threat report generated by multimodal Gemma 4 model."""
    model_config = ConfigDict(extra="ignore", str_strip_whitespace=True)

    summary: str = Field(
        ...,
        description="High-level factual summary of what the image depicts.",
        min_length=5,
        max_length=1000,
    )
    observed_indicators: list[str] = Field(
        default_factory=list,
        description="Concrete, visually verifiable UI indicators (e.g., login form, logo, domain text).",
    )
    suspicious_elements: list[str] = Field(
        default_factory=list,
        description="Potentially deceptive or irregular visual cues (e.g., misspelled brand, artificial urgency).",
    )
    supporting_evidence: list[str] = Field(
        default_factory=list,
        description="Extracts of direct visible text, layout anomalies, or visual facts from the screenshot.",
    )
    uncertainty: str = Field(
        ...,
        description="Explicit description of technical facts that cannot be verified from a screenshot alone (e.g., TLS certificate validity, DNS records).",
        min_length=5,
        max_length=800,
    )
    recommended_user_action: str = Field(
        ...,
        description="Advisory guidance for the end-user (e.g., do not input credentials, verify URL independently).",
        min_length=5,
        max_length=500,
    )
    hypothesized_threat_type: str = Field(
        default="unverified",
        description="Hypothesized category (e.g., credential_phishing, tech_support_scam, benign_dashboard).",
    )
    model_confidence: float = Field(
        default=0.5,
        ge=0.0,
        le=1.0,
        description="Model self-reported confidence score between 0.0 and 1.0.",
    )


class MultimodalAnalysisResponse(BaseModel):
    """API response contract returning separated multimodal findings, deterministic risk, and policy verdict."""
    model_config = ConfigDict(extra="forbid")

    success: bool
    threat_report: Optional[MultimodalThreatReport] = None
    risk_assessment: dict[str, Any]
    policy_decision: PolicyDecision
    policy_scope_notice: str = (
        "Agent Tool Execution Guardrail: Evaluates whether an automated agent is authorized "
        "to execute host actions; does NOT certify website safety."
    )
    provider_metadata: dict[str, Any]
    image_metadata: dict[str, Any]
    error: Optional[str] = None